 pairs=[('约14:6 “我就是道路、真理、生命” ↔ 约18:37、38', '在“各有各的真理”的时代，耶稣宣告真理是一个位格。彼拉多问“真理是什么呢？”，真理就站在他面前。'),
        ('来3:15 “你们今日若听他的话，就不可硬着心” ↔ 诗95:7、8', '“今日”是圣经中最迫切的一个词。听见上帝的声音，本身就是一个需要回应的时刻。'),
        ('雅1:22 “只要行道，不要单单听道” ↔ 太7:24-27', '“留心听”在圣经里从来不只是用耳朵听，而是听了就去行，像盖在磐石上的房子。')],
 egw=[],
 qa=[dict(t='e', q='在一个强调“说出你自己的真理”的时代，基督徒如何既尊重每个人的经历，又持守圣经的真理？', a=['经历是真实的，但经历的解释不一定正确。我们可以认真倾听一个人的感受与处境（雅1:19“快快地听，慢慢地说”），同时温柔地指出：真理的标准不是“我觉得”，而是“经上记着说”。', '真理不是用来打人的棍子，而是用来释放人的钥匙：“你们必晓得真理，真理必叫你们得以自由。”（约8:32）'], my=True)],
 shift=[('每个人都有自己的真理','真理是一个位格：耶稣基督'),('先知的信息可听可不听','先知的信息是攸关生命的指示'),('听见就是听了','听而不行，等于没有听')],
